#	system.perspective.print("confirmMoveItemClass() msg rcvd with %s"%payload)
	itemClassId = payload['inputPayload']['itemClassId']

	if payload['userInput'] == 'OK':
		info = system.kanoa.utilities.convertDatasetRowToJSON(system.kanoa.item.getItemClasses({'itemClassId': itemClassId}), 0)
		if info['itemClassId'] is None:
			system.perspective.sendMessage('showFailerToast', {'message': 'Item class was not moved. It no longer exists'})
		else:
			info['parentId'] = payload['inputPayload']['parentId']
			userId = system.kanoa.security.getIDPUserId(self.session.props.auth.user)
			try:
				retVal = system.kanoa.item.updateItemClass(info, userId)
			except:
				retVal = None

			if retVal:
				system.perspective.sendMessage('showSuccessfulToast', {'message': 'Item class has been moved'})
				system.perspective.sendMessage("refreshItemClasses", {})
			else: system.perspective.sendMessage('showFailerToast', {'message': 'Item class was not moved'})

		self.view.params.value.itemClassId = itemClassId
		self.view.refreshBinding('custom.values')	#Its path has changed even if it was already selected

	self.view.refreshBinding('custom.data')	#Update the Tree Selector (and undo the move it showed if cancelled)

	return
